extern alias InternalAnalyzers;

using InternalAnalyzers::KappaDuck.Khaos.Internal.Analyzers.Interop;

namespace KappaDuck.Khaos.Analyzers.Tests.Internal.Interop;

internal sealed class InteropImportPlacementAnalyzerTests
{
    private const string GeneratedQuit = """
        // <auto-generated/>
        namespace KappaDuck.Khaos.Windowing
        {
            internal static partial class Native
            {
                [global::System.Runtime.CompilerServices.SkipLocalsInitAttribute]
                internal static partial void Quit()
                {
                    unsafe
                    {
                        __PInvoke();
                    }

                    [global::System.Runtime.InteropServices.DllImportAttribute("SDL3", EntryPoint = "SDL_Quit", ExactSpelling = true)]
                    static extern unsafe void __PInvoke();
                }
            }
        }
        """;

    [Test]
    public async Task LibraryImportOutsideInteropShouldReportKHI009()
    {
        const string source = """
            using System.Runtime.InteropServices;

            namespace KappaDuck.Khaos.Windowing;

            internal static partial class Native
            {
                [LibraryImport("SDL3", EntryPoint = "SDL_Quit")]
                internal static partial void Quit();
            }
            """;

        AnalyzerResult result = await AnalyzerRunner<InteropImportPlacementAnalyzer>.RunAsync(source);

        await result.CompilationErrors.Should().BeEmpty();
        await result.Reported.Should().BeEqualTo("Source0.cs(8,34): error KHI009: 'Quit' imports a native function outside Interop/SDL and Interop/Win32; move it to the area of its library");
    }

    [Test]
    [Arguments("KappaDuck.Khaos.Windowing")]
    [Arguments("KappaDuck.Khaos.Interop")]
    [Arguments("KappaDuck.Khaos.Interop.Browser")]
    [Arguments("KappaDuck.Khaos.Interop.Sdl")]
    [Arguments("KappaDuck.Khaos.Windowing.Interop.SDL")]
    [Arguments("Fake.Khaos.Interop.SDL")]
    public async Task LibraryImportOutsideTheSDLAndWin32AreasShouldReportKHI009(string @namespace)
    {
        Markup source = Markup.Parse($$"""
            using System.Runtime.InteropServices;

            namespace {{@namespace}};

            internal static partial class Native
            {
                [LibraryImport("SDL3", EntryPoint = "SDL_Quit")]
                internal static partial void {|KHI009:Quit|}();
            }
            """);

        AnalyzerResult result = await AnalyzerRunner<InteropImportPlacementAnalyzer>.RunAsync(source);

        await result.CompilationErrors.Should().BeEmpty();
        await result.Located.Should().BeEqualTo(source.Expected);
    }

    [Test]
    public async Task LibraryImportInTheGlobalNamespaceShouldReportKHI009()
    {
        Markup source = Markup.Parse("""
            using System.Runtime.InteropServices;

            internal static partial class Native
            {
                [LibraryImport("SDL3", EntryPoint = "SDL_Quit")]
                internal static partial void {|KHI009:Quit|}();
            }
            """);

        AnalyzerResult result = await AnalyzerRunner<InteropImportPlacementAnalyzer>.RunAsync(source);

        await result.CompilationErrors.Should().BeEmpty();
        await result.Located.Should().BeEqualTo(source.Expected);
    }

    [Test]
    public async Task LibraryImportInANestedTypeOutsideInteropShouldReportKHI009()
    {
        Markup source = Markup.Parse("""
            using System.Runtime.InteropServices;

            namespace KappaDuck.Khaos.Windowing;

            internal static partial class Window
            {
                private static partial class Native
                {
                    [LibraryImport("user32", EntryPoint = "GetSystemMetrics")]
                    internal static partial int {|KHI009:GetSystemMetrics|}(int nIndex);
                }
            }
            """);

        AnalyzerResult result = await AnalyzerRunner<InteropImportPlacementAnalyzer>.RunAsync(source);

        await result.CompilationErrors.Should().BeEmpty();
        await result.Located.Should().BeEqualTo(source.Expected);
    }

    [Test]
    public async Task LibraryImportOutsideInteropInAFileMarkedGeneratedShouldReportKHI009()
    {
        Markup source = Markup.Parse("""
            // <auto-generated/>
            using System.Runtime.InteropServices;

            namespace KappaDuck.Khaos.Windowing;

            internal static partial class Native
            {
                [LibraryImport("SDL3", EntryPoint = "SDL_Quit")]
                internal static partial void {|KHI009:Quit|}();
            }
            """);

        AnalyzerResult result = await AnalyzerRunner<InteropImportPlacementAnalyzer>.RunAsync(source);

        await result.CompilationErrors.Should().BeEmpty();
        await result.Located.Should().BeEqualTo(source.Expected);
    }

    [Test]
    public async Task LibraryImportOutsideInteropWithItsGeneratedHalfShouldReportKHI009Once()
    {
        Markup source = Markup.Parse("""
            using System.Runtime.InteropServices;

            namespace KappaDuck.Khaos.Windowing;

            internal static partial class Native
            {
                [LibraryImport("SDL3", EntryPoint = "SDL_Quit")]
                internal static partial void {|KHI009:Quit|}();
            }
            """, GeneratedQuit);

        AnalyzerResult result = await AnalyzerRunner<InteropImportPlacementAnalyzer>.RunAsync(source);

        await result.CompilationErrors.Should().BeEmpty();
        await result.Located.Should().BeEqualTo(source.Expected);
    }

    [Test]
    [Arguments("KappaDuck.Khaos.Interop.SDL")]
    [Arguments("KappaDuck.Khaos.Interop.Win32")]
    [Arguments("KappaDuck.Khaos.Interop.SDL.Primitives")]
    [Arguments("KappaDuck.Khaos.Interop.Win32.Primitives")]
    public async Task LibraryImportInTheSDLAndWin32AreasShouldReportNothing(string @namespace)
    {
        string source = $$"""
            using System.Runtime.InteropServices;

            namespace {{@namespace}};

            internal static partial class Native
            {
                [LibraryImport("SDL3", EntryPoint = "SDL_Quit")]
                internal static partial void Quit();
            }
            """;

        AnalyzerResult result = await AnalyzerRunner<InteropImportPlacementAnalyzer>.RunAsync(source);

        await result.CompilationErrors.Should().BeEmpty();
        await result.Located.Should().BeEmpty();
    }

    [Test]
    public async Task MethodWithoutLibraryImportOutsideInteropShouldReportNothing()
    {
        const string source = """
            namespace KappaDuck.Khaos.Windowing;

            internal static class Native
            {
                internal static void Quit()
                {
                }
            }
            """;

        AnalyzerResult result = await AnalyzerRunner<InteropImportPlacementAnalyzer>.RunAsync(source);

        await result.CompilationErrors.Should().BeEmpty();
        await result.Located.Should().BeEmpty();
    }

    [Test]
    public async Task CompilationWithoutLibraryImportShouldReportNothing()
    {
        const string source = """
            namespace KappaDuck.Khaos.Windowing;

            internal static partial class Native
            {
                [System.Runtime.InteropServices.LibraryImport("SDL3", EntryPoint = "SDL_Quit")]
                internal static partial void Quit();
            }
            """;

        AnalyzerResult result = await AnalyzerRunner<InteropImportPlacementAnalyzer>.RunAsync(TestCompilation.WithoutReferences(source));

        await result.Located.Should().BeEmpty();
    }
}
